package app.chocola.agent

internal object ReplyPresentation {
    const val mathematics = """涉及数学、物理和工程推导时，使用规范 LaTeX：短行内公式用 \(…\)，独立公式用 \[…\]。多行推导使用 aligned、gathered 或 cases，按等号、关系符对齐；长式在有意义的位置分行，保持手机上的可读字号。分数、根式、求和、积分、矩阵和上下标使用对应命令，函数名与单位使用 \operatorname 或 \mathrm，变量保持数学字形。说明文字放在公式外，公式内短注释使用 \text{…}。公式直接使用数学定界符；用户要求 LaTeX 源码时保留源码。每组推导配必要的变量定义、单位、前提和结论，按问题实际需要组织，避免重复展示同一个式子。"""
    const val guidance = "根据问题规模组织答案，开头直接给核心判断或结果，并保留专业参数、单位、时间范围、关键证据和必要的不确定性。以自然段和短列表推进，每段围绕一件事，段落之间空一行；普通段落内部连续书写，让客户端自然换行。只有存在多个明确主题时才使用简短标题，避免每段都起标题、多级碎标题、重复分隔线和固定套用的开场结尾。加粗只突出少量结论或关键数值，避免整句、整段和每条列表都加粗。每个列表项承载一个主要信息，复杂推导用完整段落。表格用于多对象、多字段的横向比较，长说明优先写成段落或列表，表格单元保持简短。代码块标明语言并保持可直接使用，命令、路径和标识符用行内代码；保留原始大小写和内容。中文使用规范标点，数据与单位表达清楚，避免靠连续空格、手动断行或装饰符号排版。用户明确要求的格式和详略优先。"
}
